  if (ctx.actions) {
    var actKeys = Object.keys(ctx.actions);
    for (var ai = 0; ai < actKeys.length; ai++) {
      var av = ctx.actions[actKeys[ai]];
      if (typeof av === "string" && (av.charAt(0) === "/" || /^https?:\/\//i.test(av))) {
        out.push({ url: av, source: "html-action" });
      }
    }
  }
